    bg = max(vals, key=lambda v: sum(r.count(v) for r in grid))
    for r, row in enumerate(grid):
        nz = [c for c, v in enumerate(row) if v != bg]
        # Extend only a row that is otherwise a solid foreground run from
        # the left edge, with a nonempty background suffix.
        if nz and nz[0] == 0 and len(nz) == nz[-1] + 1 and nz[-1] < w - 1:
            for c in range(nz[-1] + 1, w):
